#' RD Power and Sample Size
#'
#' 
#' @param data .
#' @param outcome .
#' @param running .
#' @param treatment .
#' @param covs .
#' @param cutoff .
#' @param mode .
#' @param tau .
#' @param alpha .
#' @param beta .
#' @param p .
#' @param kernel .
#' @param bwselect .
#' @param vce .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$design} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$res} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$curve} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$design$asDF}
#'
#' \code{as.data.frame(results$design)}
#'
#' @export
rdpower <- function(
    data,
    outcome,
    running,
    treatment,
    covs,
    cutoff = 0,
    mode = "power",
    tau = 1,
    alpha = 0.05,
    beta = 0.8,
    p = 1,
    kernel = "triangular",
    bwselect = "mserd",
    vce = "nn",
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rdpower requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(treatment)) treatment <- jmvcore::resolveQuo(jmvcore::enquo(treatment))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(treatment), treatment, NULL),
            `if`( ! missing(covs), covs, NULL))


    options <- rdpowerOptions$new(
        outcome = outcome,
        running = running,
        treatment = treatment,
        covs = covs,
        cutoff = cutoff,
        mode = mode,
        tau = tau,
        alpha = alpha,
        beta = beta,
        p = p,
        kernel = kernel,
        bwselect = bwselect,
        vce = vce,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdpowerClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

